for proj in projects:
    proj_id = proj['project_id']
    result = apis.todoist.show_tasks(project_id=proj_id, access_token=access_token, assignee_email=paul_email, is_completed=False)
    # The response has project_id, no_section_tasks, sections
    if 'no_section_tasks' in result:
        for task in result['no_section_tasks']:
            task['project_id'] = proj_id
