        for section in result['sections']:
            for task in section.get('tasks', []):
                task['project_id'] = proj_id
                all_tasks.append(task)

print(f"Found {len(all_tasks)} incomplete tasks assigned to Paul")
for t in all_tasks:
    print(t)

